head.b:skin:
/* =========================================================
   Home Garden Lot — design tokens
   ========================================================= */
:root{
  --hgl-green:#247b49;
  --hgl-green-dark:#1b5e37;
  --hgl-green-soft:#d4ecdb;
  --hgl-green-bright:#02a848;
  --hgl-earth:#247b49;
  --hgl-sun:#22c55e;
  --hgl-bg:#f4f4f5;
  --hgl-surface:#ffffff;
  --hgl-gray:#fafafa;
  --hgl-text:#09090b;
  --hgl-text-2:#3f3f46;
  --hgl-muted:#71717a;
  --hgl-line:#e4e4e7;
  --hgl-footer:#142c1e;
  --hgl-footer-bar:#0f2217;
  --hgl-footer-text:#fafafa;
  --hgl-footer-meta:#a1a1aa;
  --hgl-radius:.5rem;
  --hgl-shadow:0 1px 2px 0 rgba(9,9,11,.05),0 10px 20px -8px rgba(9,9,11,.08);
  --hgl-shadow-lg:0 1px 2px 0 rgba(9,9,11,.05),0 20px 25px -5px rgba(9,9,11,.1),0 8px 10px -6px rgba(9,9,11,.1);
  --hgl-max:1100px;
  --hgl-read:720px;
  --hgl-sans:Inter,system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
  --hgl-serif:var(--hgl-sans);
}

/* ===== Base ===== */
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth}
body{margin:0;background:var(--hgl-bg);color:var(--hgl-text);font:400 1.0625rem/1.7 var(--hgl-sans);text-rendering:optimizeLegibility;-webkit-font-smoothing:antialiased}
img{max-width:100%;height:auto;display:block}
a{color:var(--hgl-green);text-underline-offset:.18em}
a:hover{color:var(--hgl-green-dark)}
h1,h2,h3,h4{font-family:var(--hgl-serif);font-weight:700;line-height:1.3;letter-spacing:-.025em;color:var(--hgl-text);margin:1.6em 0 .6em}
h1{font-size:clamp(1.75rem,4vw,2.5rem);margin-top:.3em}
h2{font-size:clamp(1.4rem,3vw,1.75rem)}
h3{font-size:1.25rem}
:focus-visible{outline:3px solid var(--hgl-sun);outline-offset:2px}
.hgl-skip{position:absolute;left:-999px;top:0;background:var(--hgl-green);color:#fff;padding:.6em 1em;z-index:100}
.hgl-skip:focus{left:8px;top:8px}
.hgl-wrap{max-width:var(--hgl-max);margin:0 auto;padding:0 16px}
.hgl-sr{position:absolute!important;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}

/* ===== Header ===== */
.hgl-header{background:var(--hgl-surface);box-shadow:0 1px 0 var(--hgl-line);position:sticky;top:0;z-index:50}
.hgl-header__bar{display:flex;align-items:center;gap:16px;min-height:72px}
.hgl-brand{display:flex;align-items:center;gap:10px;text-decoration:none;color:var(--hgl-text);margin:0;font:700 1.2rem/1.1 var(--hgl-serif)}
.hgl-brand-wrap{margin:0;font-size:inherit}
.hgl-brand__logo{display:block;width:auto;height:40px;max-width:180px}
.hgl-brand__tag{display:block;font:500 .72rem/1.2 var(--hgl-sans);color:var(--hgl-muted);letter-spacing:.02em}
.hgl-nav{margin-left:auto;display:flex;align-items:center;gap:4px}
.hgl-nav .section,.hgl-nav .widget{margin:0}
.hgl-nav__item--drop{position:relative}
.hgl-nav__item--drop>.hgl-nav__link::after{content:"\25BE";margin-left:6px;font-size:.8em}
.hgl-nav__sub{list-style:none;margin:0;padding:8px;position:absolute;top:100%;left:0;min-width:230px;background:var(--hgl-surface);border-radius:var(--hgl-radius);box-shadow:var(--hgl-shadow-lg);opacity:0;visibility:hidden;transform:translateY(6px);transition:opacity .15s,transform .15s;z-index:60}
.hgl-nav__item--drop:hover>.hgl-nav__sub,.hgl-nav__item--drop:focus-within>.hgl-nav__sub{opacity:1;visibility:visible;transform:none}
.hgl-nav__sub a{display:block;padding:8px 10px;border-radius:6px;color:var(--hgl-text);text-decoration:none;font-weight:600;font-size:.93rem;white-space:nowrap}
.hgl-nav__sub a:hover{background:var(--hgl-gray);color:var(--hgl-green)}
.hgl-nav__list{display:flex;flex-wrap:wrap;gap:4px;list-style:none;margin:0;padding:0}
.hgl-nav__link{display:block;padding:8px 12px;border-radius:var(--hgl-radius);text-decoration:none;color:var(--hgl-text);font-weight:700;font-size:1rem;letter-spacing:-.025em}
.hgl-nav__link:hover{background:var(--hgl-gray);color:var(--hgl-green)}
.hgl-nav__toggle{display:none;margin-left:auto;width:44px;height:44px;align-items:center;justify-content:center;background:var(--hgl-gray);border:1px solid var(--hgl-line);border-radius:var(--hgl-radius);color:var(--hgl-text);cursor:pointer}
.hgl-burger{position:relative;display:block;width:20px;height:14px}
.hgl-burger>span{position:absolute;left:0;width:100%;height:2px;border-radius:2px;background:currentColor;transition:transform .2s,opacity .2s,top .2s}
.hgl-burger>span:nth-child(1){top:0}
.hgl-burger>span:nth-child(2){top:6px}
.hgl-burger>span:nth-child(3){top:12px}
.hgl-nav__toggle[aria-expanded="true"] .hgl-burger>span:nth-child(1){top:6px;transform:rotate(45deg)}
.hgl-nav__toggle[aria-expanded="true"] .hgl-burger>span:nth-child(2){opacity:0}
.hgl-nav__toggle[aria-expanded="true"] .hgl-burger>span:nth-child(3){top:6px;transform:rotate(-45deg)}
.hgl-nav__subtoggle{display:none}
.hgl-search{display:flex;border:1px solid var(--hgl-line);border-radius:var(--hgl-radius);overflow:hidden;background:var(--hgl-gray)}
.hgl-search__input{border:0;background:transparent;padding:8px 14px;width:170px;flex:1;min-width:0;font:inherit;font-size:.9rem;color:var(--hgl-text)}
.hgl-search__btn{border:0;background:var(--hgl-green);color:#fff;padding:0 14px;cursor:pointer;font-weight:700}
.hgl-header__bar>.hgl-search{order:3}
.hgl-header__bar>.hgl-nav{order:2}
@media (max-width:900px){
  .hgl-nav__toggle{display:inline-flex}
  .hgl-nav{display:none;position:absolute;left:0;right:0;top:100%;flex-direction:column;align-items:stretch;gap:0;background:var(--hgl-surface);box-shadow:0 16px 24px -12px rgba(9,9,11,.25);padding:12px 16px 20px;max-height:calc(100vh - 72px);overflow-y:auto;overscroll-behavior:contain}
  .hgl-nav.is-open{display:flex}
  .hgl-nav .hgl-search{display:flex;order:-1;width:100%;margin:0 0 8px}
  .hgl-nav .hgl-search__input{width:auto;padding:12px 14px;font-size:1rem}
  .hgl-nav .hgl-search__btn{padding:0 18px}
  .hgl-nav__list{flex-direction:column;gap:0}
  .hgl-nav__list>li{border-bottom:1px solid var(--hgl-line)}
  .hgl-nav__list>li:last-child{border-bottom:0}
  .hgl-nav__link{padding:14px 4px;font-size:1.05rem;border-radius:0}
  .hgl-nav__link:hover{background:none}
  .hgl-nav__item--drop{display:grid;grid-template-columns:1fr 48px;align-items:center}
  .hgl-nav__item--drop>.hgl-nav__link::after{content:none}
  .hgl-nav__subtoggle{display:flex;align-items:center;justify-content:center;width:44px;height:44px;border:0;border-radius:var(--hgl-radius);background:var(--hgl-gray);color:var(--hgl-text);cursor:pointer}
  .hgl-nav__subtoggle::before{content:"\25BE";transition:transform .2s}
  .hgl-nav__subtoggle[aria-expanded="true"]::before{transform:rotate(180deg)}
  .hgl-nav__sub{grid-column:1/-1;display:none;position:static;opacity:1;visibility:visible;transform:none;box-shadow:none;padding:0 0 10px 8px;min-width:0}
  .hgl-nav__item--drop.is-open>.hgl-nav__sub{display:block}
  .hgl-nav__sub a{padding:10px 8px}
  .hgl-header__bar>.hgl-search{display:none}
}
@media (min-width:901px){.hgl-nav .hgl-search{display:none}.hgl-nav__subtoggle{display:none!important}}

/* ===== Layout ===== */
.hgl-layout{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:40px;padding:28px 16px 48px;max-width:var(--hgl-max);margin:0 auto}
.hgl-body--page .hgl-layout{grid-template-columns:minmax(0,1fr)}
.hgl-body--page .hgl-sidebar{display:none}
@media (max-width:960px){.hgl-layout{grid-template-columns:minmax(0,1fr)}}

/* ===== Hero (homepage) ===== */
.hgl-hero{background:linear-gradient(135deg,var(--hgl-green-soft) 0%,var(--hgl-bg) 70%)}
.hgl-hero__inner{padding:36px 16px 32px;max-width:var(--hgl-max);margin:0 auto}
.hgl-hero__title{margin:0 0 .4em;font-size:clamp(1.8rem,4.5vw,2.75rem)}
.hgl-hero__lead{margin:0;max-width:640px;color:var(--hgl-muted);font-size:1.1rem}
.hgl-hero__chips{display:flex;flex-wrap:wrap;gap:8px;margin-top:18px;padding:0;list-style:none}
.hgl-chip{display:inline-block;padding:6px 14px;border-radius:var(--hgl-radius);background:var(--hgl-surface);border:1px solid var(--hgl-line);text-decoration:none;font-weight:600;font-size:.9rem;color:var(--hgl-text)}
.hgl-chip:hover{border-color:var(--hgl-green);color:var(--hgl-green)}

/* ===== Archive heading ===== */
.hgl-archive{margin:0 0 24px;padding-bottom:16px;border-bottom:1px solid var(--hgl-line)}
.hgl-archive__kicker{margin:0;font-size:.8rem;font-weight:700;text-transform:uppercase;letter-spacing:.08em;color:var(--hgl-earth)}
.hgl-archive__title{margin:.2em 0 .3em}
.hgl-archive__desc{margin:0;color:var(--hgl-muted)}

/* ===== Cards ===== */
.hgl-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:24px}
.hgl-card{background:var(--hgl-surface);border-radius:var(--hgl-radius);overflow:hidden;box-shadow:var(--hgl-shadow);display:flex;flex-direction:column;transition:box-shadow .2s}
.hgl-card:hover{box-shadow:var(--hgl-shadow-lg)}
.hgl-card__media{display:block;aspect-ratio:16/9;background:var(--hgl-green-soft);overflow:hidden}
.hgl-card__img{width:100%;height:100%;object-fit:cover}
.hgl-card__body{padding:16px 18px 18px;display:flex;flex-direction:column;gap:8px;flex:1}
.hgl-card__label{font-size:.75rem;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--hgl-earth);text-decoration:none}
.hgl-card__title{margin:0;font-size:1.15rem;line-height:1.3}
.hgl-card__title a{color:var(--hgl-text);text-decoration:none}
.hgl-card__title a:hover{color:var(--hgl-green)}
.hgl-card__excerpt{margin:0;color:var(--hgl-muted);font-size:.95rem;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.hgl-card__meta{margin-top:auto;font-size:.82rem;color:var(--hgl-muted)}
.hgl-card--lead{grid-column:1/-1;display:grid;grid-template-columns:1.3fr 1fr}
.hgl-card--lead .hgl-card__media{aspect-ratio:auto;min-height:100%}
.hgl-card--lead .hgl-card__title{font-size:clamp(1.35rem,2.6vw,1.75rem)}
@media (max-width:700px){.hgl-card--lead{grid-template-columns:1fr}.hgl-card--lead .hgl-card__media{aspect-ratio:16/9}}

/* ===== Pager ===== */
.hgl-pager{display:flex;justify-content:space-between;gap:12px;margin:32px 0 0}
.hgl-pager__link{display:inline-block;padding:10px 18px;border-radius:var(--hgl-radius);background:var(--hgl-green);color:#fff;text-decoration:none;font-weight:700;box-shadow:0 4px 12px rgba(36,123,73,.2)}
.hgl-pager__link:hover{color:#fff;background:var(--hgl-green-dark)}
.hgl-pager__link--older{margin-left:auto}

/* ===== Breadcrumbs ===== */
.hgl-crumbs{font-size:.85rem;color:var(--hgl-muted);margin:0 0 8px}
.hgl-crumbs ol{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:6px}
.hgl-crumbs li+li::before{content:"\203A";margin-right:6px;color:var(--hgl-muted)}
.hgl-crumbs a{color:var(--hgl-muted);text-decoration:none}
.hgl-crumbs a:hover{color:var(--hgl-green)}

/* ===== Single post ===== */
.hgl-post{max-width:var(--hgl-read)}
.hgl-post__title{margin:.2em 0 .4em}
.hgl-post__meta{display:flex;flex-wrap:wrap;align-items:center;gap:6px 14px;font-size:.88rem;color:var(--hgl-muted);padding-bottom:16px;border-bottom:1px solid var(--hgl-line);margin-bottom:24px}
.hgl-post__author{display:flex;align-items:center;gap:8px;color:var(--hgl-text);font-weight:600;text-decoration:none}
.hgl-post__avatar{width:32px;height:32px;border-radius:50%;object-fit:cover}
.hgl-post__body{font-size:1.0625rem;overflow-wrap:break-word}
.hgl-post__body>*:first-child{margin-top:0}
.hgl-post__body p,.hgl-post__body ul,.hgl-post__body ol{margin:0 0 1.15em}
.hgl-post__body li{margin:.3em 0}
.hgl-post__body img{border-radius:10px;margin:0 auto}
.hgl-post__body .separator a{margin:0!important}
.hgl-post__body .tr-caption-container{margin:1.2em auto}
.hgl-post__body .tr-caption{font-size:.85rem;color:var(--hgl-muted);padding-top:6px}
.hgl-post__body blockquote{margin:1.4em 0;padding:4px 0 4px 18px;border-left:4px solid var(--hgl-green);color:var(--hgl-muted);font-style:italic}
.hgl-post__body table{width:100%;border-collapse:collapse;margin:1.4em 0;font-size:.95rem;display:block;overflow-x:auto}
.hgl-post__body th,.hgl-post__body td{border:1px solid var(--hgl-line);padding:10px 12px;text-align:left;vertical-align:top}
.hgl-post__body th{background:var(--hgl-green-soft);font-weight:700}
.hgl-post__body iframe{max-width:100%}
.hgl-post__body p:empty{display:none}
.hgl-post__body code{background:var(--hgl-green-soft);padding:.1em .35em;border-radius:4px;font-size:.9em}
.hgl-post__updated{font-weight:600;color:var(--hgl-green-dark)}

/* ===== Editorial blocks (use these classes in the post HTML editor) ===== */
.hgl-answer{background:var(--hgl-green-soft);border:1px solid var(--hgl-green);border-radius:var(--hgl-radius);padding:16px 20px;margin:0 0 1.5em}
.hgl-answer__label{display:block;font:700 .75rem/1 var(--hgl-sans);text-transform:uppercase;letter-spacing:.08em;color:var(--hgl-green-dark);margin-bottom:8px}
.hgl-answer p:last-child{margin-bottom:0}
.hgl-takeaways{border-left:4px solid var(--hgl-sun);background:var(--hgl-surface);padding:14px 20px;margin:1.5em 0;border-radius:0 var(--hgl-radius) var(--hgl-radius) 0;box-shadow:var(--hgl-shadow)}
.hgl-takeaways ul{margin:.4em 0 0}
.hgl-note,.hgl-warning{padding:12px 16px;border-radius:10px;margin:1.4em 0;font-size:.97rem}
.hgl-note{background:#eef5fb;border:1px solid #c8dcef;color:#1f3a52}
.hgl-warning{background:#fff6e6;border:1px solid #f0d49b;color:#5a3d06}
.hgl-faq details{border:1px solid var(--hgl-line);border-radius:10px;padding:0 16px;margin:.6em 0;background:var(--hgl-surface)}
.hgl-faq summary{cursor:pointer;font-weight:700;padding:12px 0}
.hgl-sources{font-size:.88rem;color:var(--hgl-muted);border-top:1px solid var(--hgl-line);margin-top:2em;padding-top:1em}
.hgl-tool-cta{display:flex;align-items:center;gap:14px;background:var(--hgl-surface);border:2px dashed var(--hgl-green);border-radius:var(--hgl-radius);padding:16px 18px;margin:1.6em 0}
.hgl-tool-cta a{font-weight:700}

/* ===== TOC ===== */
.hgl-toc{border:1px solid var(--hgl-line);background:var(--hgl-surface);border-radius:var(--hgl-radius);padding:0 18px;margin:0 0 1.6em}
.hgl-toc summary{cursor:pointer;font-weight:700;padding:14px 0;list-style:none;display:flex;align-items:center;justify-content:space-between}
.hgl-toc summary::-webkit-details-marker{display:none}
.hgl-toc summary::after{content:"\25BE";color:var(--hgl-green);transition:transform .2s}
.hgl-toc[open] summary::after{transform:rotate(180deg)}
.hgl-toc ol{margin:0 0 14px;padding-left:1.2em;font-size:.95rem}
.hgl-toc li{margin:.25em 0}
.hgl-toc .hgl-toc__sub{padding-left:1em;list-style:circle}
.hgl-toc a{text-decoration:none}
.hgl-post__body h2,.hgl-post__body h3{scroll-margin-top:84px}

/* ===== Share ===== */
.hgl-share{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:28px 0;padding:14px 0;border-top:1px solid var(--hgl-line);border-bottom:1px solid var(--hgl-line)}
.hgl-share__title{font-weight:700;font-size:.9rem;margin-right:4px}
.hgl-share__btn{border:1px solid var(--hgl-line);background:var(--hgl-surface);color:var(--hgl-text);border-radius:var(--hgl-radius);padding:6px 14px;font:600 .85rem var(--hgl-sans);cursor:pointer}
.hgl-share__btn:hover{border-color:var(--hgl-green);color:var(--hgl-green)}
.hgl-share__btn--pin{background:#e60023;border-color:#e60023;color:#fff}
.hgl-share__btn--pin:hover{color:#fff;opacity:.9}

/* ===== Share icons (under the title) ===== */
.hgl-share--top{flex-basis:100%;display:flex;gap:8px;margin:6px 0 0;padding:0;border:0}
.hgl-share__icon{display:inline-flex;align-items:center;justify-content:center;width:36px;height:36px;border-radius:var(--hgl-radius);border:0;background:var(--hgl-gray);color:var(--hgl-text);cursor:pointer;box-shadow:inset 0 0 0 1px var(--hgl-line)}
.hgl-share__icon svg{width:18px;height:18px;fill:currentColor}
.hgl-share__icon:hover{color:#fff;background:var(--hgl-green);box-shadow:none}
.hgl-share__icon--pinterest{background:#e60023;color:#fff;box-shadow:none}
.hgl-share__icon--facebook:hover{background:#0866ff}
.hgl-share__icon--x:hover{background:#09090b}
.hgl-share__icon--whatsapp:hover{background:#25d366}

/* ===== Converted shortcodes from the previous theme ===== */
.hgl-sc-btn{display:inline-flex;align-items:center;gap:8px;padding:12px 20px;border-radius:var(--hgl-radius);background:var(--hgl-green);color:#fff!important;font-weight:700;text-decoration:none!important;margin:4px 8px 8px 0;box-shadow:0 4px 12px rgba(36,123,73,.2)}
.hgl-sc-btn:hover{filter:brightness(.92)}
.hgl-sc-btn--center{display:flex;width:max-content;margin:8px auto}
.hgl-sc-card{display:grid;grid-template-columns:96px 1fr;gap:14px;align-items:center;background:var(--hgl-surface);border-radius:var(--hgl-radius);box-shadow:var(--hgl-shadow);padding:12px;margin:1.4em 0;text-decoration:none!important;color:var(--hgl-text)!important;border-left:4px solid var(--hgl-green)}
.hgl-sc-card:hover{box-shadow:var(--hgl-shadow-lg)}
.hgl-sc-card__img{width:96px;height:72px;border-radius:6px;object-fit:cover;background:var(--hgl-green-soft);margin:0!important}
.hgl-sc-card__kicker{display:block;font-size:.72rem;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--hgl-green)}
.hgl-sc-card__title{display:block;font-weight:700;line-height:1.35;letter-spacing:-.01em}
.hgl-sc-card__info{display:block;font-size:.85rem;color:var(--hgl-muted)}
.hgl-alert{padding:14px 18px;border-radius:var(--hgl-radius);margin:1.4em 0;border-left:4px solid}
.hgl-alert>*:last-child{margin-bottom:0}
.hgl-alert--success{background:#ecfdf3;border-color:#22c55e;color:#14532d}
.hgl-alert--info{background:#eff6ff;border-color:#3b82f6;color:#1e3a8a}
.hgl-alert--warning{background:#fffbeb;border-color:#f59e0b;color:#78350f}
.hgl-alert--error{background:#fef2f2;border-color:#ef4444;color:#7f1d1d}
.hgl-code{background:#18181b;color:#fafafa;padding:16px;border-radius:var(--hgl-radius);overflow-x:auto;font-size:.88rem;white-space:pre-wrap}
.hgl-cf{display:grid;gap:10px;max-width:560px;margin:1.4em 0}
.hgl-cf__input{width:100%;padding:12px 14px;border:1px solid var(--hgl-line);border-radius:var(--hgl-radius);background:var(--hgl-surface);font:inherit;color:var(--hgl-text)}
.hgl-cf__input:focus{outline:2px solid var(--hgl-green);border-color:transparent}
.hgl-cf .hgl-btn{border:0;cursor:pointer;justify-self:start}
.contact-form-error-message{color:#b91c1c;margin:0}
.contact-form-success-message{color:var(--hgl-green);margin:0}

/* ===== Tags ===== */
.hgl-tags{display:flex;flex-wrap:wrap;gap:8px;list-style:none;padding:0;margin:20px 0}

/* ===== Author box (E-E-A-T) ===== */
.hgl-author{display:grid;grid-template-columns:72px 1fr;gap:16px;background:var(--hgl-surface);border:1px solid var(--hgl-line);border-radius:var(--hgl-radius);padding:20px;margin:28px 0;box-shadow:var(--hgl-shadow)}
.hgl-author__img{width:72px;height:72px;border-radius:50%;object-fit:cover;background:var(--hgl-green-soft)}
.hgl-author__kicker{margin:0;font-size:.75rem;font-weight:700;text-transform:uppercase;letter-spacing:.08em;color:var(--hgl-earth)}
.hgl-author__name{margin:.1em 0 .3em;font-size:1.15rem}
.hgl-author__bio{margin:0 0 .5em;color:var(--hgl-muted);font-size:.95rem}
.hgl-author__links{font-size:.88rem;display:flex;flex-wrap:wrap;gap:12px}

/* ===== Related ===== */
.hgl-related{margin:32px 0;min-height:320px}
.hgl-related__title{margin:0 0 16px;font-size:1.35rem}
.hgl-related__grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:16px;list-style:none;margin:0;padding:0}
.hgl-related__item a{display:block;text-decoration:none;color:var(--hgl-text);font-weight:600;line-height:1.35}
.hgl-related__thumb{aspect-ratio:16/9;width:100%;object-fit:cover;border-radius:10px;background:var(--hgl-green-soft);margin-bottom:8px}

/* ===== Sidebar & widgets ===== */
.hgl-sidebar{display:flex;flex-direction:column;gap:28px}
.hgl-sidebar .widget,.hgl-footer .widget{margin:0}
.hgl-widget__title{font:700 .85rem/1.2 var(--hgl-sans);text-transform:uppercase;letter-spacing:.08em;color:var(--hgl-earth);margin:0 0 12px}
.hgl-box{background:var(--hgl-surface);border-radius:var(--hgl-radius);padding:20px;box-shadow:var(--hgl-shadow)}
.hgl-pop{list-style:none;margin:0;padding:0;counter-reset:pop}
.hgl-pop__item{display:grid;grid-template-columns:72px 1fr;gap:12px;align-items:center;padding:10px 0;border-top:1px solid var(--hgl-line)}
.hgl-pop__item:first-child{border-top:0;padding-top:0}
.hgl-pop__img{width:72px;height:54px;border-radius:8px;object-fit:cover;background:var(--hgl-green-soft)}
.hgl-pop__link{font-weight:600;font-size:.93rem;line-height:1.35;color:var(--hgl-text);text-decoration:none}
.hgl-pop__link:hover{color:var(--hgl-green)}
.hgl-labels{display:flex;flex-wrap:wrap;gap:8px;list-style:none;margin:0;padding:0}
.hgl-labels__count{color:var(--hgl-muted);font-weight:400;margin-left:4px}
.hgl-ad{min-height:280px;display:flex;align-items:center;justify-content:center}
.hgl-ad:empty{display:none}
.hgl-html{font-size:.95rem}
.hgl-tools{list-style:none;margin:0 0 14px;padding:0;display:grid;gap:2px}
.hgl-tools a{display:block;padding:7px 10px;border-radius:var(--hgl-radius);background:var(--hgl-gray);color:var(--hgl-text);text-decoration:none;font-weight:600}
.hgl-tools a:hover{background:var(--hgl-green-soft);color:var(--hgl-green)}
.hgl-btn{display:inline-block;padding:10px 16px;border-radius:var(--hgl-radius);background:var(--hgl-green);color:#fff!important;font-weight:700;text-decoration:none}
.hgl-btn:hover{background:var(--hgl-green-dark)}

/* ===== Comments (Blogger default markup, restyled because b:css=false) ===== */
.hgl-comments{margin-top:32px}
.comments h3.title,.comments .title{font-family:var(--hgl-serif);font-size:1.35rem}
.comments .comment-thread ol,.comments .comment-thread ul{list-style:none;padding-left:0}
.comments .comment{border-top:1px solid var(--hgl-line);padding:14px 0}
.comments .comment .comment-replies{padding-left:24px}
.comments .avatar-image-container img{width:36px;height:36px;border-radius:50%}
.comments .comment-block{margin-left:0}
.comments .user a{font-weight:700;text-decoration:none}
.comments .datetime{font-size:.8rem;color:var(--hgl-muted);margin-left:8px}
.comments .comment-actions a{font-size:.85rem;margin-right:12px}
.comments .comment-content{margin:.4em 0}
.comments #comment-editor{width:100%;border:0;min-height:220px}
.comment-footer,.comments .continue a{font-weight:700}

/* ===== Footer ===== */
.hgl-footer{background:var(--hgl-footer);color:var(--hgl-footer-text);margin-top:24px}
.hgl-footer a{color:var(--hgl-footer-text)}
.hgl-footer a:hover{color:var(--hgl-green-bright)}
.hgl-footer .hgl-html p{color:var(--hgl-footer-meta)}
.hgl-footer__logo{display:block;height:40px;width:auto;margin:0 0 14px}
.hgl-footer__grid{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(0,1fr) minmax(0,1fr);gap:40px;padding:44px 16px 28px;max-width:var(--hgl-max);margin:0 auto}
.hgl-footer__about .widget+.widget{margin-top:26px}
@media (max-width:900px){.hgl-footer__grid{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:32px 24px}.hgl-footer__about{grid-column:1/-1}}
.hgl-footer__text{color:var(--hgl-footer-meta);font-size:.92rem;margin:0 0 14px}
.hgl-footer__top{display:inline-block;margin-left:12px;font-weight:600}
.hgl-social{display:flex;flex-wrap:wrap;gap:8px;list-style:none;margin:0;padding:0}
.hgl-social__link{display:inline-flex;align-items:center;justify-content:center;width:38px;height:38px;border-radius:50%;background:rgba(255,255,255,.08);color:var(--hgl-footer-text);transition:background .2s,transform .2s}
.hgl-social__link svg{width:18px;height:18px;fill:currentColor}
.hgl-social__link:hover{transform:translateY(-2px);color:#fff}
.hgl-social__link--facebook:hover{background:#0866ff}
.hgl-social__link--x:hover{background:#000}
.hgl-social__link--instagram:hover{background:#e4405f}
.hgl-social__link--pinterest:hover{background:#e60023}
.hgl-social__link--youtube:hover{background:#ff0000}
.hgl-social__link--bluesky:hover{background:#0285ff}
.hgl-social__link--threads:hover{background:#000}
.hgl-social__link--whatsapp:hover{background:#25d366}
.hgl-social__link--telegram:hover{background:#26a5e4}
.hgl-social__link--flipboard:hover{background:#e12828}
.hgl-social__link--rss:hover{background:#ee802f}
.hgl-social__link--link:hover{background:var(--hgl-green)}
.hgl-social--nav{margin-top:16px;padding-top:16px;border-top:1px solid var(--hgl-line)}
.hgl-social--nav .hgl-social__link{background:var(--hgl-gray);color:var(--hgl-text);box-shadow:inset 0 0 0 1px var(--hgl-line)}
@media (min-width:901px){.hgl-social--nav{display:none}}
.hgl-footer .hgl-widget__title{color:var(--hgl-footer-text)}
.hgl-footer__list{list-style:none;margin:0;padding:0}
.hgl-footer__list li{margin:.35em 0}
.hgl-footer__list a{text-decoration:none}
.hgl-footer__bottom{background:var(--hgl-footer-bar);padding:16px;text-align:center;font-size:.85rem;color:var(--hgl-footer-meta)}

/* ===== 404 ===== */
.hgl-404{text-align:center;padding:40px 0}
.hgl-404 .hgl-search{max-width:420px;margin:20px auto}
.hgl-404 .hgl-search__input{width:100%}

/* ===== Layout editor ===== */
body#layout .hgl-layout{display:flex}
body#layout .hgl-main{width:65%}
body#layout .hgl-sidebar{width:35%}
body#layout .hgl-nav{display:block;position:static}
body#layout .hgl-footer__grid{display:flex}
body#layout .hgl-footer__grid>*{flex:1}

@media print{.hgl-header,.hgl-sidebar,.hgl-footer,.hgl-share,.hgl-related,.hgl-comments,.hgl-ad{display:none!important}}

body.script:
//
(function () {
  'use strict';
  var d = document;

  // Blogger serves ?m=1 to phones; the responsive layout makes it redundant, so tidy the address bar.
  if (/[?&]m=1/.test(location.search) && history.replaceState) {
    history.replaceState(null, '', location.href.replace(/([?&])m=1&?/, '$1').replace(/[?&]$/, ''));
  }

  var year = d.querySelector('.hgl-js-year');
  if (year) year.textContent = new Date().getFullYear();

  var toggle = d.querySelector('.hgl-nav__toggle');
  var nav = d.getElementById('hgl-nav');
  if (toggle && nav) {
    var setMenu = function (open) {
      nav.classList.toggle('is-open', open);
      toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
      toggle.setAttribute('aria-label', open ? 'Close menu' : 'Open menu');
    };
    toggle.addEventListener('click', function () { setMenu(!nav.classList.contains('is-open')); });
    d.addEventListener('keydown', function (e) {
      if (e.key === 'Escape' && nav.classList.contains('is-open')) { setMenu(false); toggle.focus(); }
    });
    d.addEventListener('click', function (e) {
      if (nav.classList.contains('is-open') && !nav.contains(e.target) && !toggle.contains(e.target)) setMenu(false);
    });
    var social = d.querySelector('.hgl-footer .hgl-social');
    if (social) {
      var copy = social.cloneNode(true);
      copy.classList.add('hgl-social--nav');
      nav.appendChild(copy);
    }
    nav.querySelectorAll('.hgl-nav__subtoggle').forEach(function (b) {
      b.addEventListener('click', function () {
        var open = b.parentNode.classList.toggle('is-open');
        b.setAttribute('aria-expanded', open ? 'true' : 'false');
        b.setAttribute('aria-label', open ? 'Hide tools' : 'Show tools');
      });
    });
  }

  // Blogger's date text follows the blog's locale settings; show a US-style date with the year.
  d.querySelectorAll('.hgl-js-date').forEach(function (t) {
    var dt = new Date(t.getAttribute('datetime'));
    if (!isNaN(dt)) t.textContent = dt.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
  });

  var body = d.getElementById('hgl-post-body');
  if (!body) return;

  // ---- Shortcodes left in posts by the previous theme ({getToc}, {getCard}, {getButton}, alerts…) ----
  var attr = function (text, name) {
    var m = text.match(new RegExp('\\$' + name + '=\\{([^}]*)\\}'));
    return m ? m[1].trim() : '';
  };
  // Replace the shortcode's whole paragraph when the shortcode is all it contains.
  var block = function (el) {
    var par = el.parentNode;
    return par && par !== body && /^(P|DIV|SPAN)$/.test(par.tagName) && par.textContent.trim() === el.textContent.trim() ? block(par) : el;
  };
  var tocSlot = null;
  body.querySelectorAll('b, strong').forEach(function (el) {
    var t = el.textContent.trim();
    if (t.charAt(0) !== '{' && t.charAt(0) !== '$') return;
    var target = block(el);
    if (/^\{getToc\}/.test(t)) {
      tocSlot = { el: target, title: attr(t, 'title'), expanded: attr(t, 'expanded') };
      return;
    }
    if (/^\{contactForm\}/.test(t)) {
      var form = d.querySelector('#hgl-contact form');
      if (form) { target.parentNode.replaceChild(form, target); return; }
    }
    if (/^\{(inAds|ads|showAds|nextPage|leftSidebar|rightSidebar|noSidebar|fullWidth|contactForm)\}|^\$ads=/.test(t)) {
      target.parentNode.removeChild(target);
    }
  });

  body.querySelectorAll('a').forEach(function (a) {
    var t = a.textContent;
    if (t.indexOf('{getButton}') > -1) {
      var label = attr(t, 'text') || 'Open';
      a.className = 'hgl-sc-btn';
      a.textContent = label;
      if (attr(t, 'color')) a.style.background = attr(t, 'color');
      var par = a.parentNode;
      if (par && /center/.test(par.getAttribute('style') || '')) a.classList.add('hgl-sc-btn--center');
    } else if (t.indexOf('{getCard}') > -1) {
      var type = attr(t, 'type') || 'post';
      var title = attr(t, 'title') || attr(t, 'text') || a.getAttribute('href');
      var card = d.createElement('a');
      card.className = 'hgl-sc-card';
      card.href = a.getAttribute('href') || '#';
      if (a.target) card.target = a.target;
      var img = d.createElement('img');
      img.className = 'hgl-sc-card__img';
      img.alt = '';
      img.width = 96;
      img.height = 72;
      img.loading = 'lazy';
      img.src = 'data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==';
      var info = d.createElement('span');
      var kick = d.createElement('span');
      kick.className = 'hgl-sc-card__kicker';
      kick.textContent = type === 'post' ? 'Related guide' : (attr(t, 'button') || 'Open');
      var ttl = d.createElement('span');
      ttl.className = 'hgl-sc-card__title';
      ttl.textContent = title;
      info.appendChild(kick);
      info.appendChild(ttl);
      if (attr(t, 'info')) {
        var meta = d.createElement('span');
        meta.className = 'hgl-sc-card__info';
        meta.textContent = attr(t, 'info');
        info.appendChild(meta);
      }
      card.appendChild(img);
      card.appendChild(info);
      block(a).parentNode.replaceChild(card, block(a));
      if (type === 'post' && card.hostname === location.hostname) {
        fetch('/feeds/posts/summary?alt=json&max-results=5&q=' + encodeURIComponent('"' + title + '"'))
          .then(function (r) { return r.json(); })
          .then(function (data) {
            var path = card.pathname;
            (data.feed.entry || []).some(function (en) {
              var l = (en.link || []).filter(function (x) { return x.rel === 'alternate'; })[0];
              if (!l || l.href.indexOf(path) === -1) return false;
              if (en.media$thumbnail) img.src = en.media$thumbnail.url.replace(/\/s\d+(-c)?\//, '/w192-h144-p-k-no-nu/').replace(/=s\d+(-c)?$/, '=w192-h144-p-k-no-nu');
              return true;
            });
          })
          .catch(function () {});
      }
    }
  });

  var alerts = { alertSuccess: 'success', alertInfo: 'info', alertWarning: 'warning', alertError: 'error', codeBox: 'code' };
  body.querySelectorAll('blockquote').forEach(function (q) {
    Object.keys(alerts).some(function (k) {
      if (q.textContent.indexOf('{' + k + '}') === -1) return false;
      var box = d.createElement(alerts[k] === 'code' ? 'pre' : 'div');
      box.className = alerts[k] === 'code' ? 'hgl-code' : 'hgl-alert hgl-alert--' + alerts[k];
      box.innerHTML = q.innerHTML.replace('{' + k + '}', '');
      q.parentNode.replaceChild(box, q);
      return true;
    });
  });

  // Any other leftover {getX} shortcode text is hidden rather than shown raw.
  body.querySelectorAll('p, b, strong, a, span').forEach(function (el) {
    if (el.isConnected && /^\s*\{get(?!Toc)[A-Za-z]+\}/.test(el.textContent) && el.textContent.length < 400) {
      var target = block(el);
      if (target.parentNode) target.parentNode.removeChild(target);
    }
  });

  // Blogger's image editor leaves stray <br>s around image blocks, creating big gaps.
  body.querySelectorAll('.separator').forEach(function (sep) {
    [sep.previousSibling, sep.nextSibling].forEach(function (n) {
      while (n && (n.nodeName === 'BR' || (n.nodeType === 3 && !n.textContent.trim()))) {
        var next = n === sep.previousSibling ? n.previousSibling : n.nextSibling;
        if (n.nodeName === 'BR') n.parentNode.removeChild(n);
        n = next;
      }
    });
  });

  // Show "Updated" only when the edit is at least a day after publish.
  var upd = d.querySelector('.hgl-js-updated');
  var pub = d.querySelector('.hgl-post__meta time');
  if (upd && pub) {
    var u = new Date(upd.getAttribute('datetime'));
    var p = new Date(pub.getAttribute('datetime'));
    if (!isNaN(u) && u - p > 864e5) {
      upd.textContent = u.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
      upd.parentNode.hidden = false;
    }
  }

  var words = (body.textContent || '').trim().split(/\s+/).length;
  var rt = d.querySelector('.hgl-js-readtime');
  if (rt && words > 120) rt.textContent = Math.max(1, Math.round(words / 230)) + ' min read';

  // External links: open safely without passing referrer-based trust.
  var host = location.hostname.replace(/^www\./, '');
  body.querySelectorAll('a[href^="http"]').forEach(function (a) {
    if (a.hostname.replace(/^www\./, '').indexOf(host) === -1) {
      a.target = '_blank';
      if (!/noopener/.test(a.rel)) a.rel = (a.rel + ' noopener').trim();
    }
  });

  // Table of contents from H2/H3, placed where {getToc} was, otherwise just before the first H2
  // so the intro (the direct answer) stays at the top. Removed when the post is too short to need one.
  var toc = d.getElementById('hgl-toc');
  // Pages get a TOC only when they ask for one with {getToc}; a stray shortcode never shows as text.
  if (toc && toc.hasAttribute('data-optin') && !tocSlot) { toc.parentNode.removeChild(toc); toc = null; }
  if (!toc && tocSlot) tocSlot.el.parentNode.removeChild(tocSlot.el);
  if (toc) {
    var heads = body.querySelectorAll('h2, h3');
    if (heads.length < 3) {
      toc.parentNode.removeChild(toc);
      if (tocSlot) tocSlot.el.parentNode.removeChild(tocSlot.el);
    } else {
      if (tocSlot) {
        tocSlot.el.parentNode.replaceChild(toc, tocSlot.el);
        if (tocSlot.title) toc.querySelector('.hgl-toc__title').textContent = tocSlot.title;
      } else {
        var firstH2 = body.querySelector('h2');
        if (firstH2) firstH2.parentNode.insertBefore(toc, firstH2);
      }
      toc.hidden = false;
      var list = toc.querySelector('.hgl-toc__list');
      var used = {};
      var sub = null;
      heads.forEach(function (h) {
        if (!h.id) {
          var base = h.textContent.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 60) || 'section';
          var id = base, n = 2;
          while (used[id] || d.getElementById(id)) id = base + '-' + n++;
          h.id = id;
        }
        used[h.id] = 1;
        var li = d.createElement('li');
        var a = d.createElement('a');
        a.href = '#' + h.id;
        a.textContent = h.textContent;
        li.appendChild(a);
        if (h.tagName === 'H3' && list.lastElementChild) {
          if (!sub || sub.parentNode !== list.lastElementChild) {
            sub = d.createElement('ol');
            sub.className = 'hgl-toc__sub';
            list.lastElementChild.appendChild(sub);
          }
          sub.appendChild(li);
        } else {
          list.appendChild(li);
          sub = null;
        }
      });
      toc.open = tocSlot && tocSlot.expanded ? tocSlot.expanded === 'true' : !window.matchMedia('(max-width: 700px)').matches;
    }
  }

  d.querySelectorAll('.hgl-share').forEach(function (share) {
    share.addEventListener('click', function (e) {
      var btn = e.target.closest('[data-net]');
      if (!btn) return;
      var url = encodeURIComponent(share.dataset.url);
      var title = encodeURIComponent(share.dataset.title);
      var img = share.dataset.image || (body.querySelector('img') || {}).src || '';
      var targets = {
        pinterest: 'https://www.pinterest.com/pin/create/button/?url=' + url + '&media=' + encodeURIComponent(img) + '&description=' + title,
        facebook: 'https://www.facebook.com/sharer/sharer.php?u=' + url,
        x: 'https://x.com/intent/post?url=' + url + '&text=' + title,
        whatsapp: 'https://wa.me/?text=' + title + '%20' + url
      };
      var net = btn.getAttribute('data-net');
      if (net === 'copy') {
        if (navigator.clipboard) navigator.clipboard.writeText(share.dataset.url).then(function () {
          if (btn.querySelector('svg')) btn.setAttribute('aria-label', 'Copied!'); else btn.textContent = 'Copied!';
          btn.style.background = 'var(--hgl-green)';
          btn.style.color = '#fff';
        });
        return;
      }
      window.open(targets[net], '_blank', 'noopener,width=640,height=560');
    });
  });

  // Related posts from the first label's JSON feed, loaded only when the section nears the viewport.
  var rel = d.querySelector('.hgl-related');
  if (rel) {
    var load = function () {
      var label = rel.getAttribute('data-label');
      var self = rel.getAttribute('data-self');
      fetch('/feeds/posts/summary/-/' + encodeURIComponent(label) + '?alt=json&max-results=7')
        .then(function (r) { return r.json(); })
        .then(function (data) {
          var grid = rel.querySelector('.hgl-related__grid');
          var shown = 0;
          (data.feed.entry || []).forEach(function (en) {
            if (shown >= 6) return;
            var link = (en.link || []).filter(function (l) { return l.rel === 'alternate'; })[0];
            if (!link || link.href.split('?')[0] === self.split('?')[0]) return;
            var thumb = en.media$thumbnail ? en.media$thumbnail.url
              .replace(/\/s\d+(-c)?\//, '/w400-h225-p-k-no-nu/')
              .replace(/=s\d+(-c)?$/, '=w400-h225-p-k-no-nu') : '';
            var li = d.createElement('li');
            li.className = 'hgl-related__item';
            var a = d.createElement('a');
            a.href = link.href;
            if (thumb) {
              var im = d.createElement('img');
              im.className = 'hgl-related__thumb';
              im.src = thumb;
              im.alt = '';
              im.width = 400;
              im.height = 225;
              im.loading = 'lazy';
              a.appendChild(im);
            }
            a.appendChild(d.createTextNode(en.title.$t));
            li.appendChild(a);
            grid.appendChild(li);
            shown++;
          });
          if (!shown) rel.parentNode.removeChild(rel);
        })
        .catch(function () { rel.parentNode.removeChild(rel); });
    };
    if ('IntersectionObserver' in window) {
      var io = new IntersectionObserver(function (entries) {
        if (entries[0].isIntersecting) { io.disconnect(); load(); }
      }, { rootMargin: '600px' });
      io.observe(rel);
    } else {
      load();
    }
  }
})();
//
